"""STL mesh -> three plotter artworks, generated by ``slice3d`` + ``trimesh``.

The geometry comes from third-party libraries; this module only selects the
per-view axes, lays out the resulting cross-section outlines and emits artwork
via the repo's existing :func:`backend.penplot.stages.layout_svg.to_svg`.

MUST NOT add sheet furniture: gallery/order sheets are composed by
``POST /v1/compose-sheet`` (AGENTS.md "One sheet source"). Output is paths only
(``fill="none"``, no ``<text>``, no ``<image>``).

The view table (``docs/stl-custom-design-plan.md``) is:

* ``broad``: slice the thinnest axis, project ``[long, mid]`` (recognisable
  face, length horizontal) — the legacy "side view";
* ``edge``: slice the second axis, project ``[long, thin]`` (profile);
* ``end``: slice the longest axis, project ``[mid, thin]`` (end-on).

``render_side_view`` stays as a compatibility alias of ``broad``. Determinism
comes from fixed slices/fit/margin/stroke, 0.06 mm simplification,
duplicate-point removal, direction normalisation and polyline sorting.
"""

from __future__ import annotations

from pathlib import Path

import numpy as np

try:  # external tools live in the user Python, not in backend/uv.lock
    import slice3d
    import trimesh
except ModuleNotFoundError:  # pragma: no cover - exercised only in backend venv
    slice3d = None  # type: ignore[assignment]
    trimesh = None  # type: ignore[assignment]

from backend.penplot.config import (
    STL_MAX_FIT_MM,
    STL_MAX_MARGIN_MM,
    STL_MAX_SLICES,
    STL_MAX_STROKE_MM,
    STL_MIN_FIT_MM,
    STL_MIN_SLICES,
    STL_MIN_STROKE_MM,
    STL_VIEWS,
)
from backend.penplot.methods import Polyline
from backend.penplot.stages.layout_svg import to_svg
from backend.penplot.stages.simplify import linesimplify

__all__ = [
    "DEFAULT_FIT_MM",
    "DEFAULT_MARGIN_MM",
    "DEFAULT_SLICES",
    "DEFAULT_STROKE_MM",
    "GENERATOR_VERSION",
    "VIEW_NAMES",
    "StlFormatError",
    "canonical_axes",
    "load_stl",
    "render_side_view",
    "render_three_views",
    "render_view",
    "view_axes",
]

DEFAULT_SLICES = 8
DEFAULT_FIT_MM = 180.0
DEFAULT_MARGIN_MM = 5.0
DEFAULT_STROKE_MM = 0.2
_SIMPLIFY_MM = 0.06
#: Stamped into every view sidecar; bump when the drawing recipe changes.
GENERATOR_VERSION = "stl-views-v1"
VIEW_NAMES = STL_VIEWS


class StlFormatError(ValueError):
    """The input is not a usable STL mesh."""


def _require_libs() -> None:
    """Fail clearly when the external STL toolchain is not installed."""
    if slice3d is None or trimesh is None:
        raise RuntimeError(
            "stl2plot needs slice3d and trimesh; install with "
            "python3 -m pip install --user slice3d 'trimesh[easy]'"
        )


def load_stl(path: Path | str) -> trimesh.Trimesh:
    """Load an ASCII/binary STL with ``slice3d``/``trimesh``."""
    _require_libs()
    try:
        mesh = slice3d.load_mesh(str(Path(path)))
    except Exception as exc:  # noqa: BLE001 - library-specific parse errors
        raise StlFormatError(f"cannot load {path}: {exc}") from exc
    if not isinstance(mesh, trimesh.Trimesh) or len(mesh.faces) == 0:
        raise StlFormatError(f"{path}: STL has no triangles")
    if not np.isfinite(np.asarray(mesh.vertices)).all():
        raise StlFormatError(f"{path}: STL has non-finite coordinates")
    return mesh


def canonical_axes(mesh: trimesh.Trimesh) -> tuple[int, int, int]:
    """Return ``(thin, mid, long)``, ranking by ``(extent, axis_index)``.

    The axis index breaks ties so a cube (or any repeated extent) maps to the
    same view on every run and on every host.
    """
    thin, mid, long = sorted(
        range(3), key=lambda i: (float(mesh.extents[i]), i)
    )
    return thin, mid, long


def view_axes(view: str, mesh: trimesh.Trimesh) -> tuple[int, int, int]:
    """Return ``(slice_axis, x_axis, y_axis)`` for one named view."""
    thin, mid, long = canonical_axes(mesh)
    table = {
        "broad": (thin, long, mid),
        "edge": (mid, long, thin),
        "end": (long, mid, thin),
    }
    if view not in table:
        raise ValueError(f"unknown view: {view}")
    return table[view]


def _as_mesh(value: trimesh.Trimesh | np.ndarray | Path | str) -> trimesh.Trimesh:
    """Accept a mesh, an STL path, or an (n, 3, 3) triangle array."""
    _require_libs()
    if isinstance(value, trimesh.Trimesh):
        return value
    if isinstance(value, (str, Path)):
        return load_stl(value)
    arr = np.asarray(value, dtype=np.float64)
    if arr.ndim == 3 and arr.shape[1:] == (3, 3):
        faces = np.arange(arr.shape[0] * 3).reshape(arr.shape[0], 3)
        return trimesh.Trimesh(vertices=arr.reshape(-1, 3), faces=faces, process=False)
    raise StlFormatError("expected a Trimesh, STL path, or (n, 3, 3) triangle array")


def _view_lines(
    mesh: trimesh.Trimesh, slices: int, view: str,
) -> list[Polyline]:
    """Project ``slice3d`` cross-section polylines into one view plane."""
    axis, x_axis, y_axis = view_axes(view, mesh)
    span = float(mesh.extents[axis])
    if span <= 0:
        raise StlFormatError(f"mesh has zero extent along the {view} slice axis")
    thickness = span / max(1, slices)
    out: list[Polyline] = []
    for section in slice3d.slice_mesh(mesh, axis="xyz"[axis], thickness=thickness):
        if section.is_empty:
            continue
        for poly in section.polylines_3d:
            pts = np.asarray(poly, dtype=np.float64)
            if pts.ndim != 2 or pts.shape[0] < 2:
                continue
            xy = pts[:, [x_axis, y_axis]]
            # Drop duplicate consecutive points from slice boundaries.
            xy = xy[np.r_[True, np.any(np.diff(xy, axis=0) != 0, axis=1)]]
            if len(xy) < 2:
                continue
            line = [(float(x), float(y)) for x, y in xy]
            if line[0] > line[-1]:
                line.reverse()
            out.append(line)
    if not out:
        raise StlFormatError(f"no cross-section lines for the {view} view")
    out.sort(key=lambda pl: (pl[0], pl[-1], tuple(pl)))
    return out


def _check_options(slices: float, fit_mm: float, margin_mm: float, stroke_mm: float) -> None:
    if not STL_MIN_SLICES <= slices <= STL_MAX_SLICES:
        raise ValueError(
            f"slices must be between {STL_MIN_SLICES} and {STL_MAX_SLICES}"
        )
    if not STL_MIN_FIT_MM <= fit_mm <= STL_MAX_FIT_MM:
        raise ValueError(
            f"fit_mm must be between {STL_MIN_FIT_MM} and {STL_MAX_FIT_MM}"
        )
    if margin_mm < 0 or margin_mm > STL_MAX_MARGIN_MM:
        raise ValueError(f"margin_mm must be between 0 and {STL_MAX_MARGIN_MM}")
    if not STL_MIN_STROKE_MM <= stroke_mm <= STL_MAX_STROKE_MM:
        raise ValueError(
            f"stroke_mm must be between {STL_MIN_STROKE_MM} and {STL_MAX_STROKE_MM}"
        )


def render_view(
    mesh: trimesh.Trimesh | np.ndarray | Path | str,
    *,
    view: str = "broad",
    slices: int = DEFAULT_SLICES,
    fit_mm: float = DEFAULT_FIT_MM,
    margin_mm: float = DEFAULT_MARGIN_MM,
    stroke_mm: float = DEFAULT_STROKE_MM,
) -> str:
    """Render artwork-only SVG for one named orthographic view of a mesh."""
    if view not in VIEW_NAMES:
        raise ValueError(f"unknown view: {view}")
    _check_options(slices, fit_mm, margin_mm, stroke_mm)

    lines = _view_lines(_as_mesh(mesh), slices, view)
    xs = [p[0] for pl in lines for p in pl]
    ys = [p[1] for pl in lines for p in pl]
    x0, y0 = min(xs), min(ys)
    w = max(max(xs) - x0, 1e-9)
    h = max(max(ys) - y0, 1e-9)
    factor = fit_mm / max(w, h)
    placed = [
        [((x - x0) * factor + margin_mm, (y - y0) * factor + margin_mm)
         for x, y in pl]
        for pl in lines
    ]
    placed = linesimplify(placed, _SIMPLIFY_MM)
    width = w * factor + 2 * margin_mm
    height = h * factor + 2 * margin_mm
    return to_svg(placed, width, height, stroke_mm=stroke_mm)


def render_three_views(
    mesh: trimesh.Trimesh | np.ndarray | Path | str,
    *,
    slices: int = DEFAULT_SLICES,
    fit_mm: float = DEFAULT_FIT_MM,
    margin_mm: float = DEFAULT_MARGIN_MM,
    stroke_mm: float = DEFAULT_STROKE_MM,
) -> dict[str, str]:
    """Render all three views in a stable order (``broad``, ``edge``, ``end``)."""
    return {
        view: render_view(
            mesh, view=view, slices=slices, fit_mm=fit_mm,
            margin_mm=margin_mm, stroke_mm=stroke_mm,
        )
        for view in VIEW_NAMES
    }


def render_side_view(
    mesh: trimesh.Trimesh | np.ndarray | Path | str,
    *,
    slices: int = DEFAULT_SLICES,
    fit_mm: float = DEFAULT_FIT_MM,
    margin_mm: float = DEFAULT_MARGIN_MM,
    stroke_mm: float = DEFAULT_STROKE_MM,
) -> str:
    """Compatibility alias: the legacy broad-face (side) view."""
    return render_view(
        mesh, view="broad", slices=slices, fit_mm=fit_mm,
        margin_mm=margin_mm, stroke_mm=stroke_mm,
    )
